"""Offline, synthetic oracle for issue #248; not a runtime trace adapter.

This module has no CLI, network access, model calls, or file writes. Its PASS
means only that a supplied synthetic observation satisfies the fixture AC.
It cannot authenticate events, attest trace completeness, or approve folding.
"""

from dataclasses import dataclass
from typing import Literal


@dataclass(frozen=True)
class Case:
    """Evaluator-owned ground truth, never generated by the solving agent."""

    order_id: str
    eta_days: int


@dataclass(frozen=True)
class Event:
    run_id: str
    kind: str
    order_id: str
    eta_days: int | None = None
    succeeded: bool = True
    actor: str = "main"


@dataclass(frozen=True)
class Result:
    verdict: Literal["PASS", "FAIL", "INCONCLUSIVE"]
    reason: str


def evaluate(
    case: Case,
    events: tuple[Event, ...],
    *,
    run_id: str,
    trace_complete: bool | None,
) -> Result:
    """Check required successful steps in order, independently of actor names.

    The caller must obtain trace completeness from outside the solving agent.
    An incomplete/unsupported observation is not zero failures or a success.
    """
    if (not isinstance(case.order_id, str) or not case.order_id
            or type(case.eta_days) is not int or case.eta_days < 0):
        raise ValueError("Case requires a nonempty order_id and nonnegative integer ETA")
    if trace_complete is not True:
        return Result("INCONCLUSIVE", "trace_completeness_unconfirmed")
    if (not isinstance(run_id, str) or not run_id
            or any(event.run_id != run_id for event in events)):
        return Result("INCONCLUSIVE", "run_identity_mismatch")
    kinds = {"lookup_order", "lookup_eta", "respond"}
    for event in events:
        if not isinstance(event.kind, str) or event.kind not in kinds:
            return Result("INCONCLUSIVE", "unsupported_event")
        if (not isinstance(event.order_id, str) or not event.order_id
                or type(event.succeeded) is not bool):
            return Result("INCONCLUSIVE", "malformed_event")
        if event.eta_days is not None and (type(event.eta_days) is not int
                                           or event.eta_days < 0):
            return Result("INCONCLUSIVE", "malformed_eta")
        if (event.succeeded and event.kind in {"lookup_eta", "respond"}
                and event.eta_days is None):
            return Result("INCONCLUSIVE", "missing_eta_result")

    order_seen = eta_seen = False
    for index, event in enumerate(events):
        if event.order_id != case.order_id:
            return Result("FAIL", "wrong_order")
        if not event.succeeded:
            continue
        if event.kind == "lookup_order":
            order_seen = True
        elif event.kind == "lookup_eta":
            if not order_seen:
                return Result("FAIL", "eta_before_order")
            if event.eta_days != case.eta_days:
                return Result("FAIL", "wrong_eta_result")
            eta_seen = True
        elif event.kind == "respond":
            if index != len(events) - 1:
                return Result("FAIL", "response_not_terminal")
            if not order_seen or not eta_seen:
                return Result("FAIL", "missing_required_step")
            if event.eta_days != case.eta_days:
                return Result("FAIL", "wrong_answer")
            return Result("PASS", "required_steps_and_answer_match")
    return Result("FAIL", "missing_final_response")
